from fractions import Fraction
p = 998244353
def brute(N, K):
    # exact DP over black ball position, uniform ordered (a,b) in 1..N^2
    dist = {i: Fraction(0) for i in range(1, N+1)}
    dist[1] = Fraction(1)
    for _ in range(K):
        nd = {i: Fraction(0) for i in range(1, N+1)}
        for j, pj in dist.items():
            if pj == 0: continue
            for a in range(1, N+1):
                for b in range(1, N+1):
                    if a == b:
                        nd[j] += pj / (N*N)
                    else:
                        # position j moves iff a==j or b==j
                        if a == j:
                            nd[b] += pj / (N*N)
                        elif b == j:
                            nd[a] += pj / (N*N)
                        else:
                            nd[j] += pj / (N*N)
        dist = nd
    return sum(i * pr for i, pr in dist.items())

def formula(N, K):
    inv2 = pow(2, p-2, p)
    r = pow(N-2, K, p) * pow(pow(N, p-2, p), K, p) % p
    return ((N+1) - (N-1)*r) % p * inv2 % p

import random
random.seed(1)
ok = True
for t in range(300):
    N = random.randint(1, 9)
    K = random.randint(1, 6)
    ev = brute(N, K)  # exact Fraction
    got = formula(N, K)
    exp = (ev.numerator % p) * pow(ev.denominator, p-2, p) % p
    if got != exp:
        ok = False
        print('MISMATCH', N, K, ev, got, exp)
print('exact-DP vs formula over 300 random small cases:', 'ALL MATCH' if ok else 'FAILED')
"

